def transform(grid):
    h, w = len(grid), len(grid[0])
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 6)]
    if not marker:
        return [row[:] for row in grid]

    color = grid[marker[0][0]][marker[0][1]]
    shape = [(r - min(x for x, _ in marker), c - min(y for _, y in marker))
             for r, c in marker]
    sh = max(r for r, _ in shape) + 1
    sw = max(c for _, c in shape) + 1

    out = [row[:] for row in grid]
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = color
    return out
